// Generated by scripts/embed-html.js from ../index.html. Do not edit by hand.
export default "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>Rep Lab</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Big+Shoulders+Display:wght@700;800;900&family=Figtree:wght@400;500;600;700&family=JetBrains+Mono:wght@500;700&display=swap\">\n<style>\n/* Layout: a gym-floor training card. Body parts are coded by bumper-plate colour per region\n   (push red, pull blue, legs yellow, arms green, core/conditioning iron grey). */\n:root {\n  --bg: #eceff2;\n  --surface: #ffffff;\n  --sunk: #e2e6ea;\n  --ink: #15181c;\n  --muted: #59616b;\n  --line: #d3d8de;\n  --accent: #c8251f;\n  --accent-ink: #ffffff;\n  --push: #d12a24;\n  --pull: #1e5cc0;\n  --legs: #e3a600;\n  --arms: #2c8a4b;\n  --core: #6b7480;\n  --good: #23824a;\n  --font-display: \"Big Shoulders Display\", \"Arial Narrow\", Impact, sans-serif;\n  --font-body: \"Figtree\", system-ui, -apple-system, \"Segoe UI\", sans-serif;\n  --font-mono: \"JetBrains Mono\", ui-monospace, SFMono-Regular, Menlo, monospace;\n  --radius: 10px;\n}\n@media (prefers-color-scheme: dark) {\n  :root:not([data-theme=\"light\"]) {\n    --bg: #0f1113; --surface: #181b1f; --sunk: #22262b; --ink: #eceef1; --muted: #9aa3ad;\n    --line: #2d3238; --accent: #ff5148; --accent-ink: #160505;\n    --push: #ff5a50; --pull: #5c93ff; --legs: #f3c330; --arms: #4fc47b; --core: #a4adb7; --good: #52c47f;\n    color-scheme: dark;\n  }\n}\n:root[data-theme=\"dark\"] {\n  --bg: #0f1113; --surface: #181b1f; --sunk: #22262b; --ink: #eceef1; --muted: #9aa3ad;\n  --line: #2d3238; --accent: #ff5148; --accent-ink: #160505;\n  --push: #ff5a50; --pull: #5c93ff; --legs: #f3c330; --arms: #4fc47b; --core: #a4adb7; --good: #52c47f;\n  color-scheme: dark;\n}\n\n* { box-sizing: border-box; }\nhtml, body { margin: 0; }\nbody {\n  background: var(--bg); color: var(--ink);\n  font-family: var(--font-body); font-size: 15px; line-height: 1.55;\n  -webkit-font-smoothing: antialiased;\n}\n.wrap { max-width: 980px; margin: 0 auto; padding-inline: 16px; padding-block: 0 120px; }\n\n/* Header */\nheader.top {\n  position: sticky; top: env(safe-area-inset-top, 0px); z-index: 10;\n  background: var(--bg); border-bottom: 1px solid var(--line);\n}\n.top-inner { max-width: 980px; margin: 0 auto; padding-inline: 16px; padding-block: 12px 0; }\n.brand { display: flex; align-items: baseline; gap: 12px; flex-wrap: wrap; }\n.brand h1 {\n  font-family: var(--font-display); font-weight: 900; font-size: 34px; line-height: 1;\n  margin: 0; letter-spacing: .01em; text-transform: uppercase;\n}\n.brand h1 span { color: var(--accent); }\n.brand p { margin: 0; color: var(--muted); font-size: 13px; }\nnav.tabs { display: flex; gap: 4px; overflow-x: auto; scrollbar-width: none; margin-top: 10px; }\nnav.tabs::-webkit-scrollbar { display: none; }\nnav.tabs button {\n  font: 600 14px var(--font-body); color: var(--muted); background: none; border: 0;\n  padding: 8px 10px 10px; border-bottom: 3px solid transparent; cursor: pointer; white-space: nowrap;\n}\nnav.tabs button[aria-selected=\"true\"] { color: var(--ink); border-bottom-color: var(--accent); }\nnav.tabs button .count {\n  font: 700 11px var(--font-mono); background: var(--accent); color: var(--accent-ink);\n  border-radius: 999px; padding: 1px 6px; margin-left: 4px;\n}\nbutton:focus-visible, a:focus-visible, input:focus-visible, select:focus-visible, summary:focus-visible {\n  outline: 2px solid var(--accent); outline-offset: 2px;\n}\n\nh2 { font-family: var(--font-display); font-weight: 800; font-size: 30px; line-height: 1.05; margin: 0; text-transform: uppercase; text-wrap: balance; }\nh3 { font-size: 17px; margin: 0; line-height: 1.3; text-wrap: balance; }\n.lead { color: var(--muted); max-width: 65ch; margin: 6px 0 0; }\n.eyebrow { font: 700 11px var(--font-mono); letter-spacing: .12em; text-transform: uppercase; color: var(--muted); }\n.section-head { padding-block: 24px 16px; display: grid; gap: 4px; }\n.mono { font-family: var(--font-mono); font-variant-numeric: tabular-nums; }\n\n/* Region dots */\n.dot { width: 10px; height: 10px; border-radius: 50%; display: inline-block; flex: none; background: var(--c, var(--core)); box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--c) 60%, #000 40%); }\n[data-region=\"push\"] { --c: var(--push); }\n[data-region=\"pull\"] { --c: var(--pull); }\n[data-region=\"legs\"] { --c: var(--legs); }\n[data-region=\"arms\"] { --c: var(--arms); }\n[data-region=\"core\"] { --c: var(--core); }\n\n/* Muscle picker */\n.picker { display: flex; flex-wrap: wrap; gap: 8px; }\n.picker button {\n  display: inline-flex; align-items: center; gap: 8px;\n  font: 600 14px var(--font-body); color: var(--ink);\n  background: var(--surface); border: 1px solid var(--line); border-radius: 999px;\n  padding: 7px 14px 7px 11px; cursor: pointer;\n}\n.picker button[aria-pressed=\"true\"] { background: var(--ink); color: var(--bg); border-color: var(--ink); }\n.legend { display: flex; flex-wrap: wrap; gap: 6px 16px; margin-top: 12px; font-size: 12px; color: var(--muted); }\n.legend span { display: inline-flex; align-items: center; gap: 6px; }\n\n.muscle-head {\n  margin-top: 24px; display: grid; grid-template-columns: 1fr auto; gap: 8px 24px; align-items: end;\n  border-top: 6px solid var(--c); padding-top: 16px;\n}\n.muscle-head .target { text-align: right; }\n.muscle-head .target b { font: 700 26px var(--font-mono); display: block; line-height: 1.1; }\n@media (max-width: 560px) { .muscle-head { grid-template-columns: 1fr; } .muscle-head .target { text-align: left; } }\n.note { margin: 12px 0 0; padding: 12px 14px; background: var(--sunk); border-radius: var(--radius); max-width: 72ch; font-size: 14px; }\n\n.ex-list { display: grid; gap: 10px; margin-top: 16px; }\n.ex {\n  background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius);\n  display: grid; grid-template-columns: 1fr auto; gap: 4px 16px; padding: 14px 16px;\n}\n.ex .meta { display: flex; flex-wrap: wrap; gap: 6px 14px; font-size: 13px; color: var(--muted); }\n.ex .meta .mono { color: var(--ink); font-weight: 700; }\n.ex .body { grid-column: 1 / -1; display: grid; gap: 6px; font-size: 14px; max-width: 75ch; }\n.ex .body p { margin: 0; }\n.ex .body .why { color: var(--muted); }\n.ex .body .why b { color: var(--ink); font-weight: 600; }\n.badge { font: 700 10px var(--font-mono); letter-spacing: .08em; text-transform: uppercase; padding: 2px 7px; border-radius: 4px; background: var(--sunk); color: var(--ink); white-space: nowrap; }\n.badge.top { background: var(--accent); color: var(--accent-ink); }\n\n.btn {\n  font: 600 13px var(--font-body); border-radius: 8px; padding: 8px 12px; cursor: pointer;\n  border: 1px solid var(--line); background: var(--surface); color: var(--ink); white-space: nowrap;\n}\n.btn.primary { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }\n.btn.added { background: var(--sunk); color: var(--good); border-color: var(--line); }\n.btn.ghost { background: none; }\n.btn.danger { color: var(--accent); }\n.btn:disabled { opacity: .5; cursor: default; }\n.ex .actions { align-self: start; }\n\n/* Programs */\n.prog-select { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 10px; }\n.prog-card {\n  text-align: left; font: inherit; color: inherit; cursor: pointer;\n  background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); padding: 14px 16px; display: grid; gap: 4px;\n}\n.prog-card[aria-pressed=\"true\"] { border-color: var(--ink); box-shadow: inset 0 0 0 1px var(--ink); }\n.prog-card .goal { font-size: 13px; color: var(--muted); }\n.prog-card b { font-family: var(--font-display); font-size: 22px; text-transform: uppercase; font-weight: 800; line-height: 1.1; }\n.week { display: flex; gap: 6px; margin-top: 16px; flex-wrap: wrap; }\n.week div { flex: 1 1 0; min-width: 38px; text-align: center; padding: 6px 2px; border-radius: 6px; background: var(--sunk); font: 700 11px var(--font-mono); color: var(--muted); }\n.week div.on { background: var(--ink); color: var(--bg); }\n.week div small { display: block; font-weight: 500; font-size: 10px; }\n.days { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 12px; margin-top: 16px; }\n.day { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); padding: 14px 16px; display: grid; gap: 10px; align-content: start; }\n.day header { display: flex; justify-content: space-between; align-items: center; gap: 8px; }\n.day ol { margin: 0; padding: 0; list-style: none; display: grid; gap: 6px; }\n.day li { display: grid; grid-template-columns: 10px 1fr auto; gap: 10px; align-items: center; font-size: 14px; }\n.day li .mono { font-size: 12px; color: var(--muted); }\n.extra { margin-top: 16px; display: grid; gap: 8px; }\n.extra p { margin: 0; }\n\n/* Science */\n.sci { display: grid; gap: 12px; }\n.claim { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); padding: 16px; display: grid; grid-template-columns: 150px 1fr; gap: 6px 20px; }\n.claim .k { font: 800 22px/1.05 var(--font-display); text-transform: uppercase; }\n.claim .k small { display: block; font: 700 11px var(--font-mono); letter-spacing: .1em; color: var(--muted); margin-top: 6px; }\n.claim .v { min-width: 0; display: grid; gap: 8px; max-width: 70ch; }\n.claim .v p { margin: 0; }\n.claim .do { font-weight: 600; }\n.claim .do::before { content: \"Do this → \"; color: var(--accent); }\n.claim .src { font-size: 12.5px; color: var(--muted); display: flex; flex-wrap: wrap; gap: 4px 12px; }\n.claim .src a { color: var(--muted); }\n@media (max-width: 640px) { .claim { grid-template-columns: 1fr; } }\n.rates { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 10px; margin-bottom: 12px; }\n.rate { background: var(--ink); color: var(--bg); border-radius: var(--radius); padding: 14px 16px; }\n.rate b { font: 700 24px var(--font-mono); display: block; }\n.rate span { font-size: 13px; opacity: .8; }\n\n/* Fuel */\n.fuel { display: grid; grid-template-columns: minmax(0, 340px) minmax(0, 1fr); gap: 16px; align-items: start; }\n@media (max-width: 760px) { .fuel { grid-template-columns: 1fr; } }\nform.calc { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); padding: 16px; display: grid; gap: 12px; }\n.field { display: grid; gap: 4px; }\n.field label, .field .lbl { font-size: 12px; font-weight: 600; color: var(--muted); text-transform: uppercase; letter-spacing: .06em; }\n.row2 { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }\ninput, select { font: 500 15px var(--font-body); color: var(--ink); background: var(--bg); border: 1px solid var(--line); border-radius: 8px; padding: 8px 10px; width: 100%; min-width: 0; }\n.seg { display: flex; border: 1px solid var(--line); border-radius: 8px; overflow: hidden; }\n.seg button { flex: 1; font: 600 13px var(--font-body); padding: 8px 6px; background: var(--bg); color: var(--muted); border: 0; cursor: pointer; }\n.seg button + button { border-left: 1px solid var(--line); }\n.seg button[aria-pressed=\"true\"] { background: var(--ink); color: var(--bg); }\n.out { display: grid; gap: 12px; }\n.big-row { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }\n.stat { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); padding: 12px; min-width: 0; }\n.stat .eyebrow { font-size: 10px; letter-spacing: .06em; }\n.stat .n { font: 700 clamp(18px, 5vw, 30px)/1.1 var(--font-mono); font-variant-numeric: tabular-nums; }\n.stat .n small { font-size: 14px; color: var(--muted); font-weight: 500; }\n.stat.hero { background: var(--ink); color: var(--bg); border-color: var(--ink); }\n.stat.hero .n small, .stat.hero .eyebrow { color: color-mix(in srgb, var(--bg) 70%, transparent); }\n.plan { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); padding: 16px; }\n.plan ul { margin: 8px 0 0; padding-left: 18px; display: grid; gap: 6px; }\n\n/* Log */\n.empty { background: var(--surface); border: 1px dashed var(--line); border-radius: var(--radius); padding: 24px; display: grid; gap: 10px; justify-items: start; }\n.empty p { margin: 0; color: var(--muted); max-width: 60ch; }\n.sess-head { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; }\n.log-ex { background: var(--surface); border: 1px solid var(--line); border-left: 6px solid var(--c); border-radius: var(--radius); padding: 14px 16px; display: grid; gap: 10px; margin-top: 10px; }\n.log-ex header { display: flex; justify-content: space-between; gap: 10px; align-items: baseline; flex-wrap: wrap; }\n.log-ex .last { font-size: 12.5px; color: var(--muted); }\n.sets { display: grid; gap: 6px; }\n.set { display: grid; grid-template-columns: 34px 1fr 1fr 44px 32px; gap: 8px; align-items: center; }\n.set .no { font: 700 13px var(--font-mono); color: var(--muted); }\n.set input[type=\"number\"] { font-family: var(--font-mono); text-align: center; padding: 7px 4px; }\n.set.done input[type=\"number\"] { border-color: var(--good); }\n.check { width: 44px; height: 36px; border-radius: 8px; border: 1px solid var(--line); background: var(--bg); color: var(--muted); cursor: pointer; font: 700 16px var(--font-body); }\n.check[aria-pressed=\"true\"] { background: var(--good); border-color: var(--good); color: #fff; }\n.x { background: none; border: 0; color: var(--muted); cursor: pointer; font-size: 18px; line-height: 1; }\n.set-labels { display: grid; grid-template-columns: 34px 1fr 1fr 44px 32px; gap: 8px; font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: .06em; font-weight: 600; text-align: center; }\n.set-labels :first-child { text-align: left; }\n.msg { font-size: 13px; color: var(--accent); }\n.hist { display: grid; gap: 8px; margin-top: 12px; }\n.hist details { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); padding: 12px 16px; }\n.hist summary { cursor: pointer; display: flex; justify-content: space-between; gap: 10px; flex-wrap: wrap; font-weight: 600; }\n.hist summary .mono { color: var(--muted); font-weight: 500; font-size: 13px; }\n.hist ul { margin: 8px 0 0; padding-left: 18px; font-size: 14px; }\n.sample-tag { font: 700 10px var(--font-mono); letter-spacing: .08em; background: var(--legs); color: #1a1400; padding: 2px 6px; border-radius: 4px; text-transform: uppercase; }\n\n/* Bottom session bar */\n.sessbar {\n  position: fixed; left: 0; right: 0; bottom: 0; z-index: 20;\n  padding: 10px 16px calc(10px + env(safe-area-inset-bottom, 0px));\n  background: var(--ink); color: var(--bg);\n  display: flex; justify-content: center;\n}\n.sessbar .in { max-width: 980px; width: 100%; display: flex; justify-content: space-between; align-items: center; gap: 12px; }\n.sessbar .btn { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }\n.disclaimer { margin-top: 32px; font-size: 12px; color: var(--muted); max-width: 70ch; }\n@media (prefers-reduced-motion: no-preference) {\n  .ex, .day, .claim { transition: border-color .15s; }\n}\n</style></head><body>\n\n<header class=\"top\">\n  <div class=\"top-inner\">\n    <div class=\"brand\">\n      <h1>Rep<span>Lab</span></h1>\n      <p>Workouts by body part, built on the training research.</p>\n    </div>\n    <nav class=\"tabs\" role=\"tablist\" id=\"tabs\"></nav>\n  </div>\n</header>\n\n<main class=\"wrap\" id=\"app\"></main>\n<div class=\"sessbar\" id=\"sessbar\" hidden></div>\n\n<script>\n/* ---------- Data ---------- */\nconst REGIONS = {\n  push: \"Push (chest, shoulders)\",\n  pull: \"Pull (back)\",\n  legs: \"Legs & glutes\",\n  arms: \"Arms\",\n  core: \"Core & conditioning\"\n};\n\nconst MUSCLES = [\n  { id: \"chest\", name: \"Chest\", region: \"push\", sets: \"10–20\",\n    note: \"Presses build most of the chest. Add one fly that loads the pecs in the stretched position, and use a low incline for the upper chest.\",\n    ex: [\n      { n: \"Barbell Bench Press\", eq: \"Barbell\", rx: \"3–4 × 5–10\", rest: \"2–3 min\", top: true,\n        cue: \"Pinch shoulder blades back and down, feet planted. Lower to the lower chest, press up and slightly back.\",\n        why: \"Heavy compound lift you can overload for years.\" },\n      { n: \"Incline Dumbbell Press\", eq: \"Dumbbells\", rx: \"3 × 8–12\", rest: \"2–3 min\", top: true,\n        cue: \"Bench at about 30°. Lower until you feel a deep chest stretch, elbows roughly 45° from your torso.\",\n        why: \"A low incline puts more of the work on the upper (clavicular) chest.\" },\n      { n: \"Weighted Dip\", eq: \"Dip bars\", rx: \"3 × 6–12\", rest: \"2 min\",\n        cue: \"Lean forward a little and sink until your shoulders are just below your elbows.\",\n        why: \"Deep stretch on the lower chest and easy to load with a belt.\" },\n      { n: \"Cable Fly\", eq: \"Cable\", rx: \"3 × 10–15\", rest: \"90 s\",\n        cue: \"Soft elbows. Open wide until the chest stretches, then bring your hands together.\",\n        why: \"Keeps tension on the muscle at long lengths, where the growth stimulus appears strongest.\" },\n      { n: \"Deficit Push-Up\", eq: \"Bodyweight\", rx: \"3 × 1–2 shy of failure\", rest: \"90 s\",\n        cue: \"Hands on plates or handles so your chest sinks below hand level.\",\n        why: \"Push-ups taken close to failure built similar chest size to bench press.\", src: \"Kikuchi & Nakazato 2017\" }\n    ] },\n  { id: \"shoulders\", name: \"Shoulders\", region: \"push\", sets: \"8–16 (side & rear)\",\n    note: \"Presses already hit the front delts hard. Side and rear delts need their own direct work, and they respond well to higher reps.\",\n    ex: [\n      { n: \"Dumbbell Lateral Raise\", eq: \"Dumbbells\", rx: \"3–4 × 12–20\", rest: \"60–90 s\", top: true,\n        cue: \"Lead with the elbows, raise to shoulder height, lower under control. Lean slightly forward.\",\n        why: \"The main builder of side delts, which create shoulder width.\" },\n      { n: \"Cable Lateral Raise\", eq: \"Cable\", rx: \"3 × 12–20\", rest: \"60–90 s\",\n        cue: \"Cable behind your body at hip height. Start with the hand across your hip.\",\n        why: \"The cable keeps tension at the bottom, where a dumbbell goes slack.\" },\n      { n: \"Overhead Press\", eq: \"Barbell or dumbbells\", rx: \"3 × 6–10\", rest: \"2–3 min\", top: true,\n        cue: \"Glutes and abs tight, press straight up and move your head through once the bar passes it.\",\n        why: \"Heavy pressing for the front delts and triceps.\" },\n      { n: \"Reverse Pec Deck\", eq: \"Machine\", rx: \"3 × 15–20\", rest: \"60–90 s\",\n        cue: \"Arms nearly straight, sweep back in a wide arc, pause, return slowly.\",\n        why: \"Isolates the rear delts, which rows only partly train.\" },\n      { n: \"Face Pull\", eq: \"Cable + rope\", rx: \"3 × 12–20\", rest: \"60–90 s\",\n        cue: \"Pull the rope toward your forehead and spread the ends apart, finishing with elbows high.\",\n        why: \"Rear delts and upper back, and good for shoulder balance.\" }\n    ] },\n  { id: \"back\", name: \"Back\", region: \"pull\", sets: \"10–20\",\n    note: \"Use one vertical pull (lats) and one horizontal pull (mid-back) each week. Let the shoulder blades move through a full range.\",\n    ex: [\n      { n: \"Pull-Up\", eq: \"Bar\", rx: \"3–4 × 6–10\", rest: \"2–3 min\", top: true,\n        cue: \"Start from a dead hang, drive elbows down to your sides, chest toward the bar.\",\n        why: \"Big lat builder. Add a belt with weight once you can do 12 clean reps.\" },\n      { n: \"Lat Pulldown\", eq: \"Cable\", rx: \"3 × 8–12\", rest: \"2 min\",\n        cue: \"Let the arms reach fully overhead at the top, pull to the upper chest.\",\n        why: \"Same pattern as a pull-up but adjustable to any strength level.\" },\n      { n: \"Chest-Supported Row\", eq: \"Dumbbells or machine\", rx: \"3–4 × 8–12\", rest: \"2 min\", top: true,\n        cue: \"Chest on an incline bench, reach long at the bottom, row elbows past your torso.\",\n        why: \"Loads the mid-back without the lower back becoming the limit.\" },\n      { n: \"Seated Cable Row\", eq: \"Cable\", rx: \"3 × 10–12\", rest: \"2 min\",\n        cue: \"Let the shoulders stretch forward, then sit tall and row to the belly.\",\n        why: \"Steady tension through a long range of motion.\" },\n      { n: \"One-Arm Dumbbell Row\", eq: \"Dumbbell\", rx: \"3 × 8–12 / side\", rest: \"90 s\",\n        cue: \"Hand and knee on a bench. Pull the dumbbell toward your hip, not your armpit.\",\n        why: \"A big stretch for the lats, one side at a time.\" }\n    ] },\n  { id: \"biceps\", name: \"Biceps\", region: \"arms\", sets: \"6–12 direct\",\n    note: \"Rows and pull-ups already work the biceps. Add curls that load the arm behind the body or at full extension.\",\n    ex: [\n      { n: \"Incline Dumbbell Curl\", eq: \"Dumbbells\", rx: \"3 × 8–15\", rest: \"90 s\", top: true,\n        cue: \"Bench at 45–60°, arms hanging behind you. Curl without moving the elbows forward.\",\n        why: \"The arm-behind-body position stretches the biceps under load.\" },\n      { n: \"EZ-Bar Curl\", eq: \"EZ bar\", rx: \"3 × 8–12\", rest: \"90 s\",\n        cue: \"Elbows pinned to the sides, full lockout at the bottom.\",\n        why: \"Easy to overload and gentler on the wrists than a straight bar.\" },\n      { n: \"Preacher Curl\", eq: \"EZ bar or machine\", rx: \"3 × 10–15\", rest: \"90 s\",\n        cue: \"Lower all the way to a straight arm, slowly. Do not bounce out of the bottom.\",\n        why: \"Hardest at the bottom, where the biceps is longest.\" },\n      { n: \"Hammer Curl\", eq: \"Dumbbells\", rx: \"3 × 10–15\", rest: \"60–90 s\",\n        cue: \"Neutral grip, thumbs up, curl across the body or straight up.\",\n        why: \"Trains the brachialis and forearm, which add arm thickness.\" }\n    ] },\n  { id: \"triceps\", name: \"Triceps\", region: \"arms\", sets: \"6–12 direct\",\n    note: \"The triceps make up about two-thirds of upper-arm size. The long head grows best when trained with the arm overhead.\",\n    ex: [\n      { n: \"Overhead Cable Triceps Extension\", eq: \"Cable + rope\", rx: \"3 × 10–15\", rest: \"90 s\", top: true,\n        cue: \"Face away from the cable, elbows by your ears, let the hands drop behind your head.\",\n        why: \"Overhead extensions built more total triceps than pushdowns in a direct comparison.\", src: \"Maeo et al. 2023\" },\n      { n: \"Close-Grip Bench Press\", eq: \"Barbell\", rx: \"3 × 6–10\", rest: \"2 min\",\n        cue: \"Hands shoulder-width, elbows tucked, touch the lower chest.\",\n        why: \"Lets the triceps handle heavy loads.\" },\n      { n: \"Cable Pushdown\", eq: \"Cable\", rx: \"3 × 10–15\", rest: \"60–90 s\",\n        cue: \"Elbows fixed at your sides, lock out fully and squeeze.\",\n        why: \"Simple, joint-friendly volume for the lateral and medial heads.\" },\n      { n: \"EZ-Bar Skull Crusher\", eq: \"EZ bar\", rx: \"3 × 8–12\", rest: \"90 s\",\n        cue: \"Lower the bar behind your head, not to the forehead, to stretch the long head.\",\n        why: \"Long-head stretch with free weights.\" }\n    ] },\n  { id: \"quads\", name: \"Quads\", region: \"legs\", sets: \"10–20\",\n    note: \"Squats grow three of the four quad heads. The rectus femoris barely grew from squats alone, so add leg extensions.\",\n    ex: [\n      { n: \"Back Squat\", eq: \"Barbell\", rx: \"3–4 × 5–10\", rest: \"3 min\", top: true,\n        cue: \"Brace, sit between your heels, go as deep as you can with a neutral back.\",\n        why: \"Full-depth squats built more glute and adductor muscle than half squats.\", src: \"Kubo et al. 2019\" },\n      { n: \"Hack Squat or Leg Press\", eq: \"Machine\", rx: \"3 × 8–12\", rest: \"2–3 min\", top: true,\n        cue: \"Feet low and shoulder-width, knees travel forward over the toes, full depth.\",\n        why: \"Heavy quad work without balance or lower-back fatigue limiting the set.\" },\n      { n: \"Bulgarian Split Squat\", eq: \"Dumbbells\", rx: \"3 × 8–12 / leg\", rest: \"2 min\",\n        cue: \"Rear foot on a bench. Short stance for quads, longer stance for glutes.\",\n        why: \"Deep single-leg stretch that fixes left/right imbalances.\" },\n      { n: \"Leg Extension\", eq: \"Machine\", rx: \"3 × 10–15\", rest: \"90 s\", top: true,\n        cue: \"Recline the seat if you can, pause at the top, lower to full knee bend.\",\n        why: \"Trains the rectus femoris that squats miss. Bottom-range reps grew the quads more than top-range reps.\", src: \"Pedrosa et al. 2022\" }\n    ] },\n  { id: \"hamstrings\", name: \"Hamstrings\", region: \"legs\", sets: \"8–16\",\n    note: \"Train both jobs of the hamstrings: hinging at the hip and bending the knee.\",\n    ex: [\n      { n: \"Romanian Deadlift\", eq: \"Barbell or dumbbells\", rx: \"3 × 6–10\", rest: \"2–3 min\", top: true,\n        cue: \"Soft knees, push the hips back until the hamstrings are fully stretched, keep the bar against your legs.\",\n        why: \"The best hip-hinge for hamstring stretch under heavy load.\" },\n      { n: \"Seated Leg Curl\", eq: \"Machine\", rx: \"3 × 10–15\", rest: \"90 s\", top: true,\n        cue: \"Lean forward slightly to stretch the hamstrings more. Control the return.\",\n        why: \"Grew the hamstrings clearly more than the lying leg curl because the hip is bent.\", src: \"Maeo et al. 2021\" },\n      { n: \"Lying Leg Curl\", eq: \"Machine\", rx: \"3 × 10–15\", rest: \"90 s\",\n        cue: \"Hips pressed into the pad, curl fully, lower slowly.\",\n        why: \"A good second curl when the seated machine is taken.\" },\n      { n: \"Nordic Curl\", eq: \"Bodyweight\", rx: \"3 × 4–8\", rest: \"2 min\",\n        cue: \"Anchor the heels, lower as slowly as you can, push up with the hands.\",\n        why: \"Very strong eccentric load. Also lowers hamstring injury risk in sport.\" }\n    ] },\n  { id: \"glutes\", name: \"Glutes\", region: \"legs\", sets: \"8–16\",\n    note: \"Deep squats and lunges already train the glutes hard. Hip thrusts and squats built similar glute size in a head-to-head study.\",\n    ex: [\n      { n: \"Barbell Hip Thrust\", eq: \"Barbell + bench\", rx: \"3–4 × 8–12\", rest: \"2 min\", top: true,\n        cue: \"Shins vertical at the top, tuck the chin, lock out with the glutes, not the lower back.\",\n        why: \"Heaviest load at the top. Matched the back squat for glute growth.\", src: \"Plotkin et al. 2023\" },\n      { n: \"Walking Lunge\", eq: \"Dumbbells\", rx: \"3 × 10–12 / leg\", rest: \"2 min\", top: true,\n        cue: \"Long steps and a slight forward lean, let the rear knee nearly touch the floor.\",\n        why: \"Deep hip flexion under load, which the glutes respond to.\" },\n      { n: \"45° Back Extension\", eq: \"Bench\", rx: \"3 × 10–15\", rest: \"90 s\",\n        cue: \"Round the upper back slightly and push the hips into the pad to bias the glutes.\",\n        why: \"Trains the glutes and hamstrings with little spinal load.\" },\n      { n: \"Cable or Machine Hip Abduction\", eq: \"Machine\", rx: \"3 × 12–20\", rest: \"60 s\",\n        cue: \"Lean forward a little, push the knees out, pause at the top.\",\n        why: \"Targets the upper glutes (glute medius) that squats underwork.\" }\n    ] },\n  { id: \"calves\", name: \"Calves\", region: \"legs\", sets: \"8–16\",\n    note: \"Calves respond best to slow reps and a pause at the bottom. Bouncing wastes most of the stimulus.\",\n    ex: [\n      { n: \"Standing Calf Raise\", eq: \"Machine or Smith\", rx: \"4 × 8–15\", rest: \"60–90 s\", top: true,\n        cue: \"Pause 2 seconds in the deepest stretch, rise all the way up, no bouncing.\",\n        why: \"Partial reps in the stretched half grew the calves more than full reps.\", src: \"Kassiano et al. 2023\" },\n      { n: \"Seated Calf Raise\", eq: \"Machine\", rx: \"3 × 12–20\", rest: \"60 s\",\n        cue: \"Same deep pause at the bottom.\",\n        why: \"Bent knees shift the work to the soleus, the deeper calf muscle.\" },\n      { n: \"Leg Press Calf Press\", eq: \"Leg press\", rx: \"3 × 10–15\", rest: \"60 s\",\n        cue: \"Balls of the feet on the edge of the plate, knees almost locked.\",\n        why: \"Lets you load the calves heavily without a dedicated machine.\" }\n    ] },\n  { id: \"core\", name: \"Core\", region: \"core\", sets: \"4–10\",\n    note: \"Ab training builds the abs but does not burn the fat over them. Visible abs come from a lower body-fat level.\",\n    ex: [\n      { n: \"Hanging Leg Raise\", eq: \"Bar\", rx: \"3 × 8–15\", rest: \"90 s\", top: true,\n        cue: \"Curl the pelvis up toward the ribs, do not just swing the legs.\",\n        why: \"Trains the lower abs and hip flexors through a long range.\" },\n      { n: \"Cable Crunch\", eq: \"Cable + rope\", rx: \"3 × 10–15\", rest: \"90 s\", top: true,\n        cue: \"Kneel, hold the rope by your head, crunch the ribs toward the hips.\",\n        why: \"Loaded spinal flexion you can progress like any other lift.\" },\n      { n: \"Ab Wheel Rollout\", eq: \"Ab wheel\", rx: \"3 × 6–12\", rest: \"90 s\",\n        cue: \"Ribs down, roll out only as far as you can without the lower back sagging.\",\n        why: \"Strong anti-extension work for the whole front of the core.\" },\n      { n: \"Pallof Press\", eq: \"Cable or band\", rx: \"3 × 10 / side\", rest: \"60 s\",\n        cue: \"Stand side-on to the cable, press the handle out and resist the twist.\",\n        why: \"Anti-rotation strength that carries over to heavy lifts.\" }\n    ] },\n  { id: \"cardio\", name: \"Fat-Loss Cardio\", region: \"core\", sets: \"2–4 sessions\",\n    note: \"The calorie deficit causes fat loss. Cardio adds to the deficit and improves heart health. Interval and steady cardio produce similar fat loss, so choose the one you will keep doing.\",\n    ex: [\n      { n: \"Daily Steps\", eq: \"None\", rx: \"8,000–10,000 / day\", rest: \"—\", top: true,\n        cue: \"Walk after meals, take calls on foot, park far away.\",\n        why: \"Everyday movement is the most adjustable part of daily calorie burn and barely affects lifting recovery.\" },\n      { n: \"Incline Treadmill Walk\", eq: \"Treadmill\", rx: \"30–45 min\", rest: \"—\", top: true,\n        cue: \"10–12% incline, about 5 km/h, conversational pace. Do not hold the rails.\",\n        why: \"Low-impact, easy to recover from, and burns plenty of calories.\" },\n      { n: \"Bike Intervals\", eq: \"Bike or rower\", rx: \"8–10 × 30 s hard / 90 s easy\", rest: \"—\",\n        cue: \"Warm up 5 minutes. Hard efforts at about 8–9 out of 10.\",\n        why: \"Similar fat loss to steady cardio in less time.\", src: \"Wewege et al. 2017\" },\n      { n: \"Sled Push\", eq: \"Sled\", rx: \"6–8 × 20 m\", rest: \"60–90 s\",\n        cue: \"Low body angle, short powerful steps, arms locked.\",\n        why: \"Hard conditioning with no eccentric phase, so it causes little soreness.\" }\n    ] }\n];\n\nconst EX = {};\nMUSCLES.forEach(m => m.ex.forEach(e => { EX[e.n] = { ...e, muscle: m.id, region: m.region }; }));\n\nconst PROGRAMS = [\n  { id: \"ul\", name: \"Upper / Lower\", days: 4, goal: \"Best all-round muscle builder\", level: \"Beginner to intermediate\",\n    week: [\"Upper A\", \"Lower A\", \"\", \"Upper B\", \"Lower B\", \"\", \"\"],\n    why: \"Each muscle is trained twice a week for about 10–16 hard sets, which sits in the range the research supports for growth.\",\n    plan: [\n      { day: \"Upper A\", items: [[\"Barbell Bench Press\",\"4 × 5–8\"],[\"Chest-Supported Row\",\"4 × 8–10\"],[\"Incline Dumbbell Press\",\"3 × 8–12\"],[\"Lat Pulldown\",\"3 × 10–12\"],[\"Dumbbell Lateral Raise\",\"3 × 12–20\"],[\"Overhead Cable Triceps Extension\",\"3 × 10–15\"],[\"Incline Dumbbell Curl\",\"3 × 10–15\"]] },\n      { day: \"Lower A\", items: [[\"Back Squat\",\"4 × 5–8\"],[\"Romanian Deadlift\",\"3 × 8–10\"],[\"Leg Extension\",\"3 × 10–15\"],[\"Seated Leg Curl\",\"3 × 10–15\"],[\"Standing Calf Raise\",\"4 × 8–12\"],[\"Hanging Leg Raise\",\"3 × 10–15\"]] },\n      { day: \"Upper B\", items: [[\"Overhead Press\",\"3 × 6–10\"],[\"Pull-Up\",\"4 × 6–10\"],[\"Weighted Dip\",\"3 × 8–12\"],[\"Seated Cable Row\",\"3 × 10–12\"],[\"Cable Fly\",\"3 × 12–15\"],[\"Reverse Pec Deck\",\"3 × 15–20\"],[\"Hammer Curl\",\"3 × 10–12\"],[\"Cable Pushdown\",\"3 × 12–15\"]] },\n      { day: \"Lower B\", items: [[\"Barbell Hip Thrust\",\"4 × 8–12\"],[\"Bulgarian Split Squat\",\"3 × 8–12 / leg\"],[\"Hack Squat or Leg Press\",\"3 × 10–15\"],[\"Lying Leg Curl\",\"3 × 10–15\"],[\"Seated Calf Raise\",\"3 × 12–20\"],[\"Cable Crunch\",\"3 × 10–15\"]] }\n    ],\n    extra: [\"Add 1–2 reps or a little weight each week. When you hit the top of the rep range on every set, add load.\", \"Every 6–8 weeks, if you feel run down, take a lighter week with half the sets.\"] },\n  { id: \"fb\", name: \"Full Body Fat Loss\", days: 3, goal: \"Lose fat, keep muscle\", level: \"Any level, short on time\",\n    week: [\"Full A\", \"Walk\", \"Full B\", \"Walk\", \"Full C\", \"Intervals\", \"\"],\n    why: \"Three lifting days keep every muscle trained twice or more per week, which is the signal to hold on to muscle in a deficit. Cardio and steps add to the deficit without hurting recovery.\",\n    plan: [\n      { day: \"Full A\", items: [[\"Back Squat\",\"3 × 6–10\"],[\"Barbell Bench Press\",\"3 × 6–10\"],[\"Chest-Supported Row\",\"3 × 8–12\"],[\"Seated Leg Curl\",\"2 × 10–15\"],[\"Dumbbell Lateral Raise\",\"2 × 12–20\"],[\"Cable Crunch\",\"2 × 10–15\"]] },\n      { day: \"Full B\", items: [[\"Romanian Deadlift\",\"3 × 6–10\"],[\"Overhead Press\",\"3 × 6–10\"],[\"Pull-Up\",\"3 × 6–10\"],[\"Leg Extension\",\"2 × 10–15\"],[\"Incline Dumbbell Curl\",\"2 × 10–15\"],[\"Overhead Cable Triceps Extension\",\"2 × 10–15\"]] },\n      { day: \"Full C\", items: [[\"Hack Squat or Leg Press\",\"3 × 8–12\"],[\"Incline Dumbbell Press\",\"3 × 8–12\"],[\"Lat Pulldown\",\"3 × 8–12\"],[\"Barbell Hip Thrust\",\"3 × 8–12\"],[\"Standing Calf Raise\",\"3 × 8–15\"],[\"Hanging Leg Raise\",\"2 × 10–15\"]] },\n      { day: \"Cardio\", items: [[\"Incline Treadmill Walk\",\"30–45 min (Walk days)\"],[\"Bike Intervals\",\"8–10 rounds (Intervals day)\"],[\"Daily Steps\",\"8,000–10,000 every day\"]] }\n    ],\n    extra: [\"Keep the weight on the bar. Lifting heavy is what tells your body to keep muscle during a diet.\", \"Eat high protein (see Fuel) and aim to lose 0.5–1% of body weight per week.\"] },\n  { id: \"ppl\", name: \"Push / Pull / Legs\", days: 6, goal: \"Maximum volume for experienced lifters\", level: \"Intermediate to advanced\",\n    week: [\"Push\", \"Pull\", \"Legs\", \"Push\", \"Pull\", \"Legs\", \"\"],\n    why: \"Running the rotation twice gives each muscle 2 sessions and 14–20 sets a week. Use it only if you can recover from six days.\",\n    plan: [\n      { day: \"Push\", items: [[\"Barbell Bench Press\",\"4 × 5–8\"],[\"Overhead Press\",\"3 × 6–10\"],[\"Incline Dumbbell Press\",\"3 × 8–12\"],[\"Cable Fly\",\"3 × 12–15\"],[\"Cable Lateral Raise\",\"4 × 12–20\"],[\"Overhead Cable Triceps Extension\",\"3 × 10–15\"],[\"Cable Pushdown\",\"2 × 12–15\"]] },\n      { day: \"Pull\", items: [[\"Pull-Up\",\"4 × 6–10\"],[\"Chest-Supported Row\",\"3 × 8–12\"],[\"One-Arm Dumbbell Row\",\"3 × 8–12 / side\"],[\"Face Pull\",\"3 × 12–20\"],[\"Reverse Pec Deck\",\"3 × 15–20\"],[\"Incline Dumbbell Curl\",\"3 × 8–15\"],[\"Hammer Curl\",\"2 × 10–15\"]] },\n      { day: \"Legs\", items: [[\"Back Squat\",\"4 × 5–8\"],[\"Romanian Deadlift\",\"3 × 6–10\"],[\"Leg Extension\",\"3 × 10–15\"],[\"Seated Leg Curl\",\"3 × 10–15\"],[\"Walking Lunge\",\"2 × 10–12 / leg\"],[\"Standing Calf Raise\",\"4 × 8–15\"],[\"Cable Crunch\",\"3 × 10–15\"]] }\n    ],\n    extra: [\"Second rotation: swap the main lift (e.g. Hack Squat for Back Squat, Weighted Dip for Bench) to vary the stimulus.\", \"If performance drops two sessions in a row, cut a set from each exercise.\"] }\n];\n\nconst SCIENCE = [\n  { k: \"Volume\", tag: \"Muscle\", claim: \"More weekly sets build more muscle, up to a point. About 10 or more hard sets per muscle per week clearly beat fewer, with smaller gains beyond about 20.\",\n    do: \"Start at 10–12 hard sets per muscle per week. Add sets only if progress stalls and you recover well.\",\n    src: [\"Schoenfeld, Ogborn & Krieger 2017, J Sports Sci\", \"Pelland et al. 2024, volume & frequency meta-regression\"] },\n  { k: \"Frequency\", tag: \"Muscle\", claim: \"Training a muscle at least twice a week produced more growth than once a week when volume was spread out.\",\n    do: \"Hit every muscle 2× per week (Upper/Lower or Full Body).\",\n    src: [\"Schoenfeld, Ogborn & Krieger 2016, Sports Med\"] },\n  { k: \"Effort\", tag: \"Muscle\", claim: \"Light and heavy loads grow muscle about equally when sets are taken close to failure. Growth improves as sets get closer to failure.\",\n    do: \"Use about 5–30 reps per set and end each set 0–3 reps short of failure. Go to failure mainly on isolation moves.\",\n    src: [\"Schoenfeld et al. 2017, low vs. high load meta-analysis\", \"Refalo et al. 2023, Sports Med\"] },\n  { k: \"Overload\", tag: \"Muscle\", claim: \"Adding reps or adding load each week both produce similar growth. What matters is doing more over time.\",\n    do: \"Log every set. Beat last time by a rep or a small weight jump.\",\n    src: [\"Plotkin et al. 2022, PeerJ\"] },\n  { k: \"Stretch\", tag: \"Muscle\", claim: \"Exercises that load a muscle when it is stretched built more muscle in several direct comparisons (seated vs. lying curls, overhead vs. pushdowns, bottom-half partials).\",\n    do: \"Use full range of motion and control the stretched part of every rep. Pick the stretch-loaded exercises marked TOP PICK.\",\n    src: [\"Maeo et al. 2021, MSSE\", \"Maeo et al. 2023, Eur J Sport Sci\", \"Pedrosa et al. 2022\", \"Wolf et al. 2023, range-of-motion meta-analysis\"] },\n  { k: \"Rest\", tag: \"Muscle\", claim: \"Three-minute rests built more muscle than one-minute rests on compound lifts, because you complete more reps.\",\n    do: \"Rest 2–3 min on big lifts, 60–90 s on isolation. Use supersets only to save time.\",\n    src: [\"Schoenfeld et al. 2016, J Strength Cond Res\", \"Singer et al. 2024, rest interval meta-analysis\"] },\n  { k: \"Protein\", tag: \"Both\", claim: \"Gains from training levelled off at about 1.6 g of protein per kg of body weight per day. The upper estimate was 2.2 g/kg.\",\n    do: \"Eat 1.6–2.2 g/kg per day (0.7–1 g per lb), split over 3–5 meals. Go to the high end when dieting.\",\n    src: [\"Morton et al. 2018, Br J Sports Med\", \"Helms et al. 2014, JISSN\"] },\n  { k: \"Deficit\", tag: \"Fat loss\", claim: \"Fat loss requires eating fewer calories than you burn. Losing about 0.7% of body weight per week kept more muscle than losing 1.4%.\",\n    do: \"Aim to lose 0.5–1% of body weight per week. Weigh daily and compare weekly averages.\",\n    src: [\"Garthe et al. 2011, IJSNEM\", \"Helms et al. 2014, JISSN\"] },\n  { k: \"Keep muscle\", tag: \"Fat loss\", claim: \"In a hard 4-week deficit, people who lifted and ate high protein gained lean mass while losing more fat than a lower-protein group.\",\n    do: \"Keep lifting heavy while dieting and keep protein high. Do not switch to only cardio.\",\n    src: [\"Longland et al. 2016, Am J Clin Nutr\"] },\n  { k: \"Cardio\", tag: \"Fat loss\", claim: \"Interval training and steady cardio produced similar fat loss. Intervals take less time.\",\n    do: \"Do 2–4 cardio sessions a week plus 8,000–10,000 daily steps, whichever style you enjoy.\",\n    src: [\"Wewege et al. 2017, Obes Rev\"] },\n  { k: \"Sleep\", tag: \"Both\", claim: \"Dieters sleeping 5.5 hours lost 55% less fat and more lean mass than when sleeping 8.5 hours on the same diet.\",\n    do: \"Get 7–9 hours. It is the cheapest recovery tool there is.\",\n    src: [\"Nedeltcheva et al. 2010, Ann Intern Med\"] },\n  { k: \"Creatine\", tag: \"Both\", claim: \"Creatine monohydrate is the best-supported supplement for strength and lean mass gains and is safe for healthy adults.\",\n    do: \"Take 3–5 g per day, any time. No loading phase is needed.\",\n    src: [\"Kreider et al. 2017, ISSN position stand\"] },\n  { k: \"Spot reduction\", tag: \"Fat loss\", claim: \"Six weeks of ab exercises did not reduce belly fat compared with a control group.\",\n    do: \"Train abs for strength and shape. Lose belly fat through the overall calorie deficit.\",\n    src: [\"Vispute et al. 2011, J Strength Cond Res\"] }\n];\n\n/* ---------- State ---------- */\nconst store = {\n  get(k, d) { try { const v = localStorage.getItem(\"replab:\" + k); return v ? JSON.parse(v) : d; } catch (e) { return d; } },\n  set(k, v) { try { localStorage.setItem(\"replab:\" + k, JSON.stringify(v)); } catch (e) {} }\n};\nconst TABS = [[\"workouts\",\"Workouts\"],[\"programs\",\"Programs\"],[\"science\",\"Science\"],[\"fuel\",\"Fuel\"],[\"log\",\"Log\"]];\nconst initialTab = (location.hash || \"\").slice(1);\nconst state = {\n  tab: TABS.some(t => t[0] === initialTab) ? initialTab : store.get(\"tab\", \"workouts\"),\n  muscle: store.get(\"muscle\", \"chest\"),\n  program: store.get(\"program\", \"ul\"),\n  session: store.get(\"session\", null),\n  history: store.get(\"history\", null),\n  fuel: store.get(\"fuel\", { unit: \"kg\", sex: \"m\", age: 30, weight: 80, height: 178, activity: 1.55, goal: \"lose\", rate: 0.75 }),\n  msg: \"\",\n  confirmDiscard: false\n};\nconst SAMPLE_HISTORY = [{ sample: true, date: Date.now() - 3 * 864e5, name: \"Upper A (example)\", items: [\n  { n: \"Barbell Bench Press\", sets: [{ w: 70, r: 8 }, { w: 70, r: 7 }, { w: 70, r: 6 }] },\n  { n: \"Chest-Supported Row\", sets: [{ w: 26, r: 10 }, { w: 26, r: 9 }, { w: 26, r: 9 }] },\n  { n: \"Dumbbell Lateral Raise\", sets: [{ w: 10, r: 16 }, { w: 10, r: 14 }, { w: 10, r: 13 }] }\n] }];\nif (!state.history) state.history = SAMPLE_HISTORY;\n\nfunction save() {\n  store.set(\"tab\", state.tab); store.set(\"muscle\", state.muscle); store.set(\"program\", state.program);\n  store.set(\"session\", state.session); store.set(\"history\", state.history); store.set(\"fuel\", state.fuel);\n}\n\nconst esc = s => String(s).replace(/[&<>\"']/g, c => ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\" }[c]));\nconst pubmed = t => \"https://pubmed.ncbi.nlm.nih.gov/?term=\" + encodeURIComponent(t.replace(/,.*$/, \"\").replace(/ et al\\./, \"\").replace(/&/g, \"\"));\nconst $ = s => document.querySelector(s);\n\n/* ---------- Session helpers ---------- */\nfunction inSession(n) { return !!(state.session && state.session.items.some(i => i.n === n)); }\nfunction defaultSets(rx) { const m = /^(\\d+)/.exec(rx || \"\"); return Math.min(m ? +m[1] : 3, 6); }\nfunction addToSession(n, rx, name) {\n  if (!state.session) state.session = { started: Date.now(), name: name || \"Custom session\", items: [] };\n  if (inSession(n)) return;\n  const c = defaultSets(rx || EX[n].rx);\n  state.session.items.push({ n, rx: rx || EX[n].rx, sets: Array.from({ length: c }, () => ({ w: \"\", r: \"\", done: false })) });\n}\nfunction removeFromSession(n) {\n  if (!state.session) return;\n  state.session.items = state.session.items.filter(i => i.n !== n);\n  if (!state.session.items.length) state.session = null;\n}\nfunction lastFor(n) {\n  for (const h of state.history) {\n    const it = h.items.find(i => i.n === n);\n    if (it && it.sets.length) {\n      const best = it.sets.reduce((a, b) => (b.w * b.r > a.w * a.r ? b : a));\n      return { date: h.date, best, count: it.sets.length };\n    }\n  }\n  return null;\n}\nconst unit = () => state.fuel.unit === \"lb\" ? \"lb\" : \"kg\";\nconst fmtDate = t => new Date(t).toLocaleDateString(undefined, { weekday: \"short\", month: \"short\", day: \"numeric\" });\n\n/* ---------- Render ---------- */\nfunction renderTabs() {\n  const n = state.session ? state.session.items.length : 0;\n  $(\"#tabs\").innerHTML = TABS.map(([id, label]) =>\n    `<button role=\"tab\" data-tab=\"${id}\" aria-selected=\"${state.tab === id}\">${label}${id === \"log\" && n ? `<span class=\"count\">${n}</span>` : \"\"}</button>`).join(\"\");\n}\n\nfunction renderWorkouts() {\n  const m = MUSCLES.find(x => x.id === state.muscle) || MUSCLES[0];\n  return `\n  <div class=\"section-head\">\n    <span class=\"eyebrow\">Exercise library</span>\n    <h2>Pick a body part</h2>\n    <p class=\"lead\">Top picks are the exercises with the strongest evidence or the best stretch under load. Tap <b>Add</b> to build today's session.</p>\n  </div>\n  <div class=\"picker\">${MUSCLES.map(x => `<button data-muscle=\"${x.id}\" data-region=\"${x.region}\" aria-pressed=\"${x.id === m.id}\"><span class=\"dot\"></span>${x.name}</button>`).join(\"\")}</div>\n  <div class=\"legend\">${Object.entries(REGIONS).map(([k, v]) => `<span data-region=\"${k}\"><span class=\"dot\"></span>${v}</span>`).join(\"\")}</div>\n\n  <div class=\"muscle-head\" data-region=\"${m.region}\">\n    <div><span class=\"eyebrow\">${REGIONS[m.region]}</span><h2>${m.name}</h2></div>\n    <div class=\"target\"><span class=\"eyebrow\">${m.id === \"cardio\" ? \"Per week\" : \"Hard sets / week\"}</span><b>${m.sets}</b></div>\n  </div>\n  <p class=\"note\">${m.note}</p>\n  <div class=\"ex-list\">\n    ${m.ex.map(e => `\n      <article class=\"ex\">\n        <div>\n          <h3>${e.n} ${e.top ? '<span class=\"badge top\">Top pick</span>' : \"\"}</h3>\n          <div class=\"meta\"><span class=\"mono\">${e.rx}</span><span>Rest ${e.rest}</span><span>${e.eq}</span></div>\n        </div>\n        <div class=\"actions\">${inSession(e.n)\n          ? `<button class=\"btn added\" data-remove=\"${esc(e.n)}\">✓ Added</button>`\n          : `<button class=\"btn primary\" data-add=\"${esc(e.n)}\">+ Add</button>`}</div>\n        <div class=\"body\">\n          <p><b>How:</b> ${e.cue}</p>\n          <p class=\"why\"><b>Why:</b> ${e.why}${e.src ? ` <a href=\"${pubmed(e.src)}\" target=\"_blank\" rel=\"noopener\">(${e.src})</a>` : \"\"}</p>\n        </div>\n      </article>`).join(\"\")}\n  </div>`;\n}\n\nfunction renderPrograms() {\n  const p = PROGRAMS.find(x => x.id === state.program) || PROGRAMS[0];\n  const dn = [\"Mon\",\"Tue\",\"Wed\",\"Thu\",\"Fri\",\"Sat\",\"Sun\"];\n  return `\n  <div class=\"section-head\">\n    <span class=\"eyebrow\">Weekly plans</span>\n    <h2>Choose a program</h2>\n    <p class=\"lead\">Each plan follows the evidence: every muscle twice a week, 10–20 hard sets, big lifts first. Start any day as a session and log it.</p>\n  </div>\n  <div class=\"prog-select\">${PROGRAMS.map(x => `\n    <button class=\"prog-card\" data-program=\"${x.id}\" aria-pressed=\"${x.id === p.id}\">\n      <span class=\"eyebrow\">${x.days} lifting days</span><b>${x.name}</b>\n      <span class=\"goal\">${x.goal} · ${x.level}</span>\n    </button>`).join(\"\")}</div>\n  <div class=\"week\">${p.week.map((d, i) => `<div class=\"${d ? \"on\" : \"\"}\">${dn[i]}<small>${d || \"Rest\"}</small></div>`).join(\"\")}</div>\n  <p class=\"note\">${p.why}</p>\n  <div class=\"days\">${p.plan.map((d, di) => `\n    <section class=\"day\">\n      <header><h3>${d.day}</h3><button class=\"btn primary\" data-startday=\"${di}\">Start session</button></header>\n      <ol>${d.items.map(([n, rx]) => `<li data-region=\"${EX[n].region}\"><span class=\"dot\"></span><span>${n}</span><span class=\"mono\">${rx}</span></li>`).join(\"\")}</ol>\n    </section>`).join(\"\")}</div>\n  <div class=\"extra plan\"><span class=\"eyebrow\">Progression</span>${p.extra.map(x => `<p>${x}</p>`).join(\"\")}</div>`;\n}\n\nfunction renderScience() {\n  return `\n  <div class=\"section-head\">\n    <span class=\"eyebrow\">What the research says</span>\n    <h2>The fastest realistic route</h2>\n    <p class=\"lead\">These rules come from meta-analyses and controlled trials. Each links to PubMed so you can read the source. \"Fastest\" still has limits, and here they are.</p>\n  </div>\n  <div class=\"rates\">\n    <div class=\"rate\"><b>0.5–1%</b><span>of body weight lost per week is the fat-loss pace that best protects muscle.</span></div>\n    <div class=\"rate\"><b>~0.25–0.5%</b><span>of body weight gained per month on a lean bulk for intermediates. Beginners can gain faster. (Coaching rule of thumb.)</span></div>\n    <div class=\"rate\"><b>1.6–2.2 g/kg</b><span>of protein per day covers almost everyone's muscle-building needs.</span></div>\n  </div>\n  <div class=\"sci\">${SCIENCE.map(s => `\n    <article class=\"claim\">\n      <div class=\"k\">${s.k}<small>${s.tag.toUpperCase()}</small></div>\n      <div class=\"v\">\n        <p>${s.claim}</p>\n        <p class=\"do\">${s.do}</p>\n        <div class=\"src\">${s.src.map(x => `<a href=\"${pubmed(x)}\" target=\"_blank\" rel=\"noopener\">${x}</a>`).join(\"\")}</div>\n      </div>\n    </article>`).join(\"\")}</div>`;\n}\n\nfunction calcFuel() {\n  const f = state.fuel;\n  const kg = f.unit === \"lb\" ? f.weight * 0.4536 : +f.weight;\n  const cm = f.unit === \"lb\" ? f.height * 2.54 : +f.height;\n  const bmr = 10 * kg + 6.25 * cm - 5 * f.age + (f.sex === \"m\" ? 5 : -161);\n  const tdee = bmr * f.activity;\n  let target = tdee, change = 0;\n  if (f.goal === \"lose\") { change = -(f.rate / 100) * kg * 7700 / 7; target = tdee + change; }\n  if (f.goal === \"build\") { change = tdee * 0.1; target = tdee + change; }\n  target = Math.max(target, f.sex === \"m\" ? 1500 : 1200);\n  const pLo = Math.round(kg * (f.goal === \"lose\" ? 1.8 : 1.6));\n  const pHi = Math.round(kg * (f.goal === \"lose\" ? 2.4 : 2.2));\n  const weekly = f.goal === \"lose\" ? kg * f.rate / 100 : f.goal === \"build\" ? kg * 0.0025 * 7 / 30 : 0;\n  return { kg, bmr, tdee, target, pLo, pHi, weekly };\n}\n\nfunction renderFuel() {\n  const f = state.fuel, r = calcFuel(), u = f.unit, hu = u === \"lb\" ? \"in\" : \"cm\";\n  const wkW = u === \"lb\" ? r.weekly / 0.4536 : r.weekly;\n  const seg = (key, opts) => `<div class=\"seg\">${opts.map(([v, l]) => `<button type=\"button\" data-fuel=\"${key}\" data-val=\"${v}\" aria-pressed=\"${String(f[key]) === String(v)}\">${l}</button>`).join(\"\")}</div>`;\n  return `\n  <div class=\"section-head\">\n    <span class=\"eyebrow\">Calories & protein</span>\n    <h2>Fuel your goal</h2>\n    <p class=\"lead\">Uses the Mifflin–St Jeor equation, the most accurate common formula for resting energy needs. Treat the number as a starting point, then adjust by the scale after two weeks.</p>\n  </div>\n  <div class=\"fuel\">\n    <form class=\"calc\" id=\"calc\">\n      <div class=\"field\"><span class=\"lbl\">Goal</span>${seg(\"goal\", [[\"lose\",\"Lose fat\"],[\"recomp\",\"Recomp\"],[\"build\",\"Build muscle\"]])}</div>\n      ${f.goal === \"lose\" ? `<div class=\"field\"><span class=\"lbl\">Pace (% body weight / week)</span>${seg(\"rate\", [[0.5,\"0.5%\"],[0.75,\"0.75%\"],[1,\"1%\"]])}</div>` : \"\"}\n      <div class=\"row2\">\n        <div class=\"field\"><span class=\"lbl\">Sex</span>${seg(\"sex\", [[\"m\",\"Male\"],[\"f\",\"Female\"]])}</div>\n        <div class=\"field\"><span class=\"lbl\">Units</span>${seg(\"unit\", [[\"kg\",\"kg/cm\"],[\"lb\",\"lb/in\"]])}</div>\n      </div>\n      <div class=\"row2\">\n        <div class=\"field\"><label for=\"f-weight\">Weight (${u})</label><input id=\"f-weight\" type=\"number\" inputmode=\"decimal\" min=\"30\" max=\"700\" value=\"${f.weight}\" data-num=\"weight\"></div>\n        <div class=\"field\"><label for=\"f-height\">Height (${hu})</label><input id=\"f-height\" type=\"number\" inputmode=\"decimal\" min=\"40\" max=\"250\" value=\"${f.height}\" data-num=\"height\"></div>\n      </div>\n      <div class=\"row2\">\n        <div class=\"field\"><label for=\"f-age\">Age</label><input id=\"f-age\" type=\"number\" inputmode=\"numeric\" min=\"14\" max=\"100\" value=\"${f.age}\" data-num=\"age\"></div>\n        <div class=\"field\"><label for=\"f-activity\">Activity</label>\n          <select id=\"f-activity\" data-num=\"activity\">\n            ${[[1.2,\"Desk job, little exercise\"],[1.375,\"Light: 1–3 workouts\"],[1.55,\"Moderate: 3–5 workouts\"],[1.725,\"High: 6–7 workouts\"],[1.9,\"Very high: physical job + training\"]]\n              .map(([v, l]) => `<option value=\"${v}\" ${+f.activity === v ? \"selected\" : \"\"}>${l}</option>`).join(\"\")}\n          </select>\n        </div>\n      </div>\n    </form>\n    <div class=\"out\" id=\"fuel-out\">${renderFuelOut(r, wkW)}</div>\n  </div>`;\n}\nfunction renderFuelOut(r, wkW) {\n  const f = state.fuel, u = unit();\n  const goalLine = f.goal === \"lose\" ? `Expected loss: <b class=\"mono\">${wkW.toFixed(2)} ${u}/week</b>`\n    : f.goal === \"build\" ? `Expected gain: about <b class=\"mono\">${(wkW * 4.3).toFixed(1)} ${u}/month</b> (more if you are new to lifting)`\n    : `Eat at maintenance, lift hard, and keep protein high. Best for beginners and people returning to training.`;\n  return `\n    <div class=\"big-row\">\n      <div class=\"stat hero\"><span class=\"eyebrow\">Daily calories</span><div class=\"n\">${Math.round(r.target / 10) * 10}<small> kcal</small></div></div>\n      <div class=\"stat\"><span class=\"eyebrow\">Protein / day</span><div class=\"n\">${r.pLo}–${r.pHi}<small> g</small></div></div>\n      <div class=\"stat\"><span class=\"eyebrow\">Maintenance</span><div class=\"n\">${Math.round(r.tdee / 10) * 10}<small> kcal</small></div></div>\n    </div>\n    <div class=\"plan\">\n      <span class=\"eyebrow\">Your plan</span>\n      <p style=\"margin:6px 0 0\">${goalLine}</p>\n      <ul>\n        <li>Protein first: about ${Math.round(r.pHi / 4)} g across 4 meals.</li>\n        <li>Fill the rest of your calories with mostly whole foods. Keep fat at least 0.6 g/kg (${Math.round(r.kg * 0.6)} g) for hormone health.</li>\n        <li>Weigh yourself every morning and compare weekly averages. If the average does not move as expected for 2 weeks, change calories by 150–200.</li>\n        ${f.goal === \"lose\" ? \"<li>Walk 8,000–10,000 steps a day and keep lifting heavy. Use the Full Body Fat Loss program.</li>\" : \"<li>Use the Upper / Lower program and add a rep or some weight every week.</li>\"}\n        <li>Sleep 7–9 hours, and consider 3–5 g of creatine monohydrate daily.</li>\n      </ul>\n    </div>`;\n}\n\nfunction renderLog() {\n  const s = state.session, u = unit();\n  let html = `<div class=\"section-head\"><span class=\"eyebrow\">Training log</span><h2>Today's session</h2>\n    <p class=\"lead\">Fill in weight and reps, tick each set, then finish. Your last result shows above each exercise so you know what to beat. Everything is saved on this device.</p></div>`;\n  if (!s) {\n    html += `<div class=\"empty\"><p>No session running. Start a program day, or add exercises from the Workouts tab.</p>\n      <div style=\"display:flex;gap:8px;flex-wrap:wrap\"><button class=\"btn primary\" data-goto=\"programs\">Pick a program day</button><button class=\"btn\" data-goto=\"workouts\">Browse exercises</button></div></div>`;\n  } else {\n    const done = s.items.reduce((a, i) => a + i.sets.filter(x => x.done).length, 0);\n    const total = s.items.reduce((a, i) => a + i.sets.length, 0);\n    html += `<div class=\"sess-head\"><div><h3>${esc(s.name)}</h3><span class=\"mono\" style=\"color:var(--muted);font-size:13px\">${done}/${total} sets done · started ${new Date(s.started).toLocaleTimeString([], { hour: \"numeric\", minute: \"2-digit\" })}</span></div>\n      <div style=\"display:flex;gap:8px;flex-wrap:wrap\">\n        ${state.confirmDiscard\n          ? `<button class=\"btn danger\" data-discard=\"yes\">Yes, discard</button><button class=\"btn\" data-discard=\"no\">Keep</button>`\n          : `<button class=\"btn ghost\" data-discard=\"ask\">Discard</button>`}\n        <button class=\"btn primary\" data-finish>Finish & save</button>\n      </div></div>\n      ${state.msg ? `<p class=\"msg\">${esc(state.msg)}</p>` : \"\"}`;\n    s.items.forEach((it, i) => {\n      const e = EX[it.n], last = lastFor(it.n);\n      html += `<section class=\"log-ex\" data-region=\"${e.region}\">\n        <header><h3>${esc(it.n)}</h3><span class=\"mono\" style=\"font-size:12px;color:var(--muted)\">Target ${esc(it.rx)} · rest ${e.rest}</span></header>\n        <div class=\"last\">${last ? `Last time (${fmtDate(last.date)}): best set <b class=\"mono\">${last.best.w} ${u} × ${last.best.r}</b>. Beat it by a rep or a little weight.` : \"First time logging this one. Pick a weight you can lift for the target reps with 1–3 reps to spare.\"}</div>\n        <div class=\"set-labels\"><span>Set</span><span>${u}</span><span>Reps</span><span>Done</span><span></span></div>\n        <div class=\"sets\">${it.sets.map((st, j) => `\n          <div class=\"set ${st.done ? \"done\" : \"\"}\">\n            <span class=\"no\">${j + 1}</span>\n            <input type=\"number\" inputmode=\"decimal\" id=\"w-${i}-${j}\" data-set=\"${i}-${j}-w\" value=\"${esc(st.w)}\" placeholder=\"${last ? last.best.w : \"–\"}\" aria-label=\"Weight set ${j + 1}\">\n            <input type=\"number\" inputmode=\"numeric\" id=\"r-${i}-${j}\" data-set=\"${i}-${j}-r\" value=\"${esc(st.r)}\" placeholder=\"${last ? last.best.r : \"–\"}\" aria-label=\"Reps set ${j + 1}\">\n            <button class=\"check\" data-done=\"${i}-${j}\" aria-pressed=\"${st.done}\" aria-label=\"Mark set ${j + 1} done\">✓</button>\n            <button class=\"x\" data-delset=\"${i}-${j}\" aria-label=\"Remove set ${j + 1}\">×</button>\n          </div>`).join(\"\")}</div>\n        <div style=\"display:flex;gap:8px\"><button class=\"btn\" data-addset=\"${i}\">+ Set</button><button class=\"btn ghost\" data-remove=\"${esc(it.n)}\">Remove exercise</button></div>\n      </section>`;\n    });\n  }\n  html += `<div class=\"section-head\" style=\"padding-top:32px\"><span class=\"eyebrow\">History</span><h2>Past sessions</h2></div>`;\n  if (!state.history.length) html += `<p class=\"lead\">Finished sessions show up here.</p>`;\n  else html += `<div class=\"hist\">${state.history.slice(0, 30).map(h => {\n    const vol = h.items.reduce((a, i) => a + i.sets.reduce((b, s) => b + s.w * s.r, 0), 0);\n    return `<details><summary><span>${esc(h.name)} ${h.sample ? '<span class=\"sample-tag\">Example</span>' : \"\"}</span><span class=\"mono\">${fmtDate(h.date)} · ${Math.round(vol).toLocaleString()} ${u} volume</span></summary>\n      <ul>${h.items.map(i => `<li>${esc(i.n)}: <span class=\"mono\">${i.sets.map(s => `${s.w}×${s.r}`).join(\", \")}</span></li>`).join(\"\")}</ul></details>`;\n  }).join(\"\")}</div>`;\n  return html;\n}\n\nfunction renderBar() {\n  const bar = $(\"#sessbar\"), s = state.session;\n  if (!s || state.tab === \"log\") { bar.hidden = true; return; }\n  bar.hidden = false;\n  bar.innerHTML = `<div class=\"in\"><span><b>${esc(s.name)}</b> · ${s.items.length} exercise${s.items.length === 1 ? \"\" : \"s\"}</span><button class=\"btn\" data-goto=\"log\">Open log →</button></div>`;\n}\n\nfunction render() {\n  renderTabs();\n  const app = $(\"#app\");\n  app.innerHTML = ({ workouts: renderWorkouts, programs: renderPrograms, science: renderScience, fuel: renderFuel, log: renderLog }[state.tab])()\n    + `<p class=\"disclaimer\">General education, not medical advice. Check with a doctor before starting if you have a health condition, injury, or are pregnant.</p>`;\n  renderBar();\n  save();\n}\n\n/* ---------- Events ---------- */\ndocument.addEventListener(\"click\", ev => {\n  const t = ev.target.closest(\"button\");\n  if (!t) return;\n  const d = t.dataset;\n  if (d.tab || d.goto) { state.tab = d.tab || d.goto; state.msg = \"\"; state.confirmDiscard = false; history.replaceState(null, \"\", \"#\" + state.tab); render(); window.scrollTo(0, 0); return; }\n  if (d.muscle) { state.muscle = d.muscle; render(); return; }\n  if (d.add) { addToSession(d.add); render(); return; }\n  if (d.remove) { removeFromSession(d.remove); render(); return; }\n  if (d.program) { state.program = d.program; render(); return; }\n  if (d.startday !== undefined) {\n    const p = PROGRAMS.find(x => x.id === state.program), day = p.plan[+d.startday];\n    state.session = { started: Date.now(), name: `${p.name} · ${day.day}`, items: [] };\n    day.items.forEach(([n, rx]) => addToSession(n, rx));\n    state.tab = \"log\"; state.msg = \"\"; history.replaceState(null, \"\", \"#log\"); render(); window.scrollTo(0, 0); return;\n  }\n  if (d.fuel) {\n    const v = d.val, f = state.fuel;\n    if (d.fuel === \"unit\" && v !== f.unit) {\n      if (v === \"lb\") { f.weight = Math.round(f.weight / 0.4536); f.height = Math.round(f.height / 2.54); }\n      else { f.weight = Math.round(f.weight * 0.4536); f.height = Math.round(f.height * 2.54); }\n    }\n    f[d.fuel] = d.fuel === \"rate\" ? +v : v;\n    render(); return;\n  }\n  if (d.done) { const [i, j] = d.done.split(\"-\").map(Number); const st = state.session.items[i].sets[j]; st.done = !st.done; state.msg = \"\"; render(); return; }\n  if (d.addset !== undefined) { const it = state.session.items[+d.addset]; const prev = it.sets[it.sets.length - 1] || {}; it.sets.push({ w: prev.w || \"\", r: \"\", done: false }); render(); return; }\n  if (d.delset) { const [i, j] = d.delset.split(\"-\").map(Number); state.session.items[i].sets.splice(j, 1); render(); return; }\n  if (d.discard) {\n    if (d.discard === \"ask\") state.confirmDiscard = true;\n    else if (d.discard === \"yes\") { state.session = null; state.confirmDiscard = false; }\n    else state.confirmDiscard = false;\n    render(); return;\n  }\n  if (d.finish !== undefined) {\n    const items = state.session.items.map(it => ({ n: it.n, sets: it.sets.filter(s => s.done && +s.r > 0).map(s => ({ w: +s.w || 0, r: +s.r })) })).filter(it => it.sets.length);\n    if (!items.length) { state.msg = \"Tick at least one set with reps filled in, then finish.\"; render(); return; }\n    state.history = state.history.filter(h => !h.sample);\n    state.history.unshift({ date: Date.now(), name: state.session.name, items });\n    state.session = null; state.msg = \"\"; render(); window.scrollTo(0, 0); return;\n  }\n});\n\ndocument.addEventListener(\"input\", ev => {\n  const el = ev.target;\n  if (el.dataset.set) {\n    const [i, j, k] = el.dataset.set.split(\"-\");\n    state.session.items[+i].sets[+j][k] = el.value;\n    store.set(\"session\", state.session);\n  }\n  if (el.dataset.num) {\n    const v = parseFloat(el.value);\n    if (!isFinite(v) || v <= 0) return;\n    state.fuel[el.dataset.num] = v;\n    store.set(\"fuel\", state.fuel);\n    const r = calcFuel();\n    const wkW = state.fuel.unit === \"lb\" ? r.weekly / 0.4536 : r.weekly;\n    $(\"#fuel-out\").innerHTML = renderFuelOut(r, wkW);\n  }\n});\ndocument.addEventListener(\"submit\", ev => ev.preventDefault());\nwindow.addEventListener(\"hashchange\", () => {\n  const h = location.hash.slice(1);\n  if (TABS.some(t => t[0] === h) && h !== state.tab) { state.tab = h; render(); }\n});\n\nrender();\n</script>\n</body></html>";
